import sys
from collections import deque


def main():
    data = sys.stdin.read().split()
    m = int(data[0])
    codes = set(data[1:1 + m])
    start, target = data[1 + m], data[2 + m]
    if target not in codes:
        print(-1)
        return
    dist = {start: 0}
    dq = deque([start])
    while dq:
        u = dq.popleft()
        if u == target:
            print(dist[u])
            return
        for p in range(4):
            for d in '0123456789':
                if d != u[p]:
                    v = u[:p] + d + u[p + 1:]
                    if v in codes and v not in dist:
                        dist[v] = dist[u] + 1
                        dq.append(v)
    print(-1)


