data = sys.stdin.read().split()
m = int(data[0])
codes = list(dict.fromkeys(data[1:1 + m]))
start, target = data[1 + m], data[2 + m]


def adjacent(a, b):
    return sum(x != y for x, y in zip(a, b)) == 1


dist = {start: 0}
queue = [start]
for u in queue:
    for v in codes:
        if v not in dist and adjacent(u, v):
            dist[v] = dist[u] + 1
            queue.append(v)
print(dist[target] if target in codes and target in dist else -1)

